"""
Demo A -- The metric geometry of truth: prefix balls, ultrametricity, dimension.

Self-contained (standard library only). Demonstrates, numerically:
  * d(x,y) = 2^-m, m = first index where two truth streams disagree;
  * closed balls of radius 2^-n coincide with prefix-agreement classes;
  * the strong triangle inequality d(x,z) <= max(d(x,y), d(y,z));
  * box dimension = lim log2 N(n)/n, the entropy rate of the prefix language;
  * the paired-dependency truth set has N(n) = 2^ceil(n/2), hence dimension 1/2;
  * the golden-mean truth set has dimension log2((1+sqrt5)/2) = log2 of the
    spectral radius of its transfer matrix.
"""

from __future__ import annotations

import math
import random
from typing import Callable, List, Sequence, Tuple

Word = Tuple[int, ...]


# ---- the metric ------------------------------------------------------------

def cantor_dist(x: Sequence[int], y: Sequence[int]) -> float:
    """First-disagreement distance between two (finite views of) truth streams."""
    for k in range(min(len(x), len(y))):
        if x[k] != y[k]:
            return 2.0 ** (-k)
    return 0.0


def agree_to(n: int, x: Sequence[int], y: Sequence[int]) -> bool:
    return all(x[k] == y[k] for k in range(n))


# ---- theories as prefix languages ------------------------------------------

def paired_dependency(w: Word) -> bool:
    """Every odd statement restates the even one before it."""
    return all(w[i] == w[i - 1] for i in range(1, len(w), 2))


def golden_mean(w: Word) -> bool:
    """No two consecutive statements are simultaneously true."""
    return all(not (w[i] == 1 and w[i + 1] == 1) for i in range(len(w) - 1))


def anarchy(w: Word) -> bool:
    return True


def admissible(pred: Callable[[Word], bool], n: int) -> List[Word]:
    level: List[Word] = [()]
    for _ in range(n):
        level = [w + (b,) for w in level for b in (0, 1) if pred(w + (b,))]
    return level


def dimension_table(pred: Callable[[Word], bool], nmax: int) -> List[Tuple[int, int, float]]:
    return [(n, len(admissible(pred, n)), math.log2(len(admissible(pred, n))) / n)
            for n in range(1, nmax + 1)]


def spectral_radius_2x2(m: Sequence[Sequence[float]]) -> float:
    tr = m[0][0] + m[1][1]
    det = m[0][0] * m[1][1] - m[0][1] * m[1][0]
    disc = tr * tr - 4 * det
    return max(abs((tr + math.sqrt(disc)) / 2), abs((tr - math.sqrt(disc)) / 2))


def main() -> None:
    rng = random.Random(20260803)
    L = 24

    print("Balls are prefix classes:")
    x = [rng.randint(0, 1) for _ in range(L)]
    for m in range(6):
        y = x[:m] + [1 - x[m]] + [rng.randint(0, 1) for _ in range(L - m - 1)]
        checks = all((cantor_dist(x, y) <= 2.0 ** -n + 1e-15) == agree_to(n, x, y)
                     for n in range(L))
        print(f"  branch at m={m}: d = {cantor_dist(x, y):.9f} = 2^-{m};  "
              f"ball/cylinder equivalence holds at every depth: {checks}")

    print("\nStrong triangle inequality over 50000 random triples:")
    viol = iso = 0
    for _ in range(50000):
        a = [rng.randint(0, 1) for _ in range(L)]
        b = a[:rng.randint(0, 8)] + [rng.randint(0, 1) for _ in range(L)]
        c = b[:rng.randint(0, 8)] + [rng.randint(0, 1) for _ in range(L)]
        dab, dbc, dac = cantor_dist(a, b[:L]), cantor_dist(b[:L], c[:L]), cantor_dist(a, c[:L])
        if dac > max(dab, dbc) + 1e-15:
            viol += 1
        s = sorted([dab, dbc, dac])
        if abs(s[2] - s[1]) < 1e-15:
            iso += 1
    print(f"  violations: {viol};  isosceles triangles: {iso}/50000 (all of them)")

    print("\nBox dimension = lim log2 N(n)/n:")
    for name, pred, exact in [("anarchy", anarchy, 1.0),
                              ("paired dependency", paired_dependency, 0.5),
                              ("golden-mean taboo", golden_mean,
                               math.log2((1 + 5 ** 0.5) / 2))]:
        rows = dimension_table(pred, 16)
        tail = ", ".join(f"n={n}:{est:.4f}" for n, _, est in rows[-4:])
        print(f"  {name:<20} exact {exact:.6f} | estimates {tail}")

    print("\nPaired dependency: N(n) = 2^ceil(n/2) exactly for n <= 16:",
          all(N == 2 ** math.ceil(n / 2) for n, N, _ in dimension_table(paired_dependency, 16)))
    print("Fair-coin measure bound N(n)2^-n at n = 40:",
          f"{2.0 ** (math.ceil(40 / 2) - 40):.3e}  (measure zero in the limit)")

    rho = spectral_radius_2x2([[1, 1], [1, 0]])
    print(f"\nGolden-mean transfer matrix [[1,1],[1,0]]: rho = {rho:.9f}, "
          f"dimension = log2 rho = {math.log2(rho):.9f}")
    print("Counting and spectra agree: the dimension of truth is an eigenvalue.")


if __name__ == "__main__":
    main()

