function FIRST_DISAGREEMENT(x, y, budget):
    for k = 0, 1, ..., budget - 1:
        if x(k) != y(k): return k
    return NONE

function CANTOR_DISTANCE(x, y, budget):
    m <- FIRST_DISAGREEMENT(x, y, budget)
    if m = NONE: return (2^(-budget), exact = FALSE)   # upper bound only
    return (2^(-m), exact = TRUE)

function IN_CLOSED_BALL(centre, y, n):
    # correct because B(centre, 2^-n) IS the depth-n prefix class
    return FIRST_DISAGREEMENT(centre, y, n) = NONE

function ULTRAMETRIC_HOLDS(x, y, z, budget):
    dxy <- CANTOR_DISTANCE(x, y, budget); dyz <- CANTOR_DISTANCE(y, z, budget)
    dxz <- CANTOR_DISTANCE(x, z, budget)
    return dxz <= max(dxy, dyz)

function ISOSCELES_WITNESS(x, y, z, budget):
    (a, b, c) <- sort(dxy, dyz, dxz)
    return c = b        # the two longest sides always coincide

function PREFIX_LEVELS(admissible, nmax):
    L[0] <- { empty word }
    for k = 0 .. nmax - 1:
        L[k+1] <- { w concat b : w in L[k], b in {0,1}, admissible(w concat b) }
    return L

function BOX_DIMENSION_ESTIMATES(admissible, nmax):
    L <- PREFIX_LEVELS(admissible, nmax)
    for n = 1 .. nmax:
        N <- |L[n]|
        emit (n, N, log2(N) / n)          # -> dim_B as n -> infinity

function WALK_COUNTS(M, start, n):        # finite-state shortcut
    v <- start
    repeat n times: v <- v * M            # vector-matrix product
    return sum(v)                          # = N(n) up to a constant factor

function PERRON_ROOT(M, iters):
    v <- all-ones vector
    repeat iters times:
        w <- M v; lambda <- max_i |w_i|; v <- w / lambda
    return lambda

function FINITE_STATE_DIMENSION(M):
    return log2(PERRON_ROOT(M))            # dimension of truth = log of an eigenvalue
